/**
 * The pure BayesRoute CLI command logic.
 *
 * {@link runCli} takes the argv tail, an injected I/O surface, and a context, and returns a process
 * exit code. It touches no Node built-in directly: every read, write, and print goes through {@link
 * CliIo}, so the whole command surface is unit-testable in-process. The bin in `index.ts` binds this to
 * the real filesystem and process streams.
 *
 * @packageDocumentation
 */

import { armSummary } from '../arms/index.js';
import { isBayesRouteError } from '../errors.js';
import { createBayesRoute } from '../index.js';
import { makeOutcome } from '../outcome/index.js';
import { createMemoryStore, decodeSnapshot, encodeSnapshot, loadSnapshot } from '../store/index.js';
import type { ArmSummary, PosteriorStore, StoreSnapshot } from '../types.js';
import { DEFAULT_SCALE, DEFAULT_WEIGHTS } from '../utility/index.js';
import { numberOption, parseArgs, stringOption } from './args.js';

/** Process exit codes (sysexits-style). */
export const EXIT_OK = 0;
export const EXIT_ERROR = 1;
export const EXIT_USAGE = 64;
export const EXIT_DATA = 65;
export const EXIT_NOINPUT = 66;

/** The injected I/O surface, so command logic stays free of Node built-ins. */
export interface CliIo {
  readFile(path: string): Promise<string>;
  writeFile(path: string, data: string): Promise<void>;
  readStdin(): Promise<string>;
  out(line: string): void;
  err(line: string): void;
}

/** Runtime context, currently just the resolved package version. */
export interface CliContext {
  readonly version: string;
}

const USAGE = [
  'bayesroute, Thompson-sampling Bayesian router for LLMs across quality, cost, and latency',
  '',
  'Usage:',
  '  bayesroute route   --models <a,b,c> [--domain <d>] [--seed <n>] [--store <file>]',
  '  bayesroute observe --store <file> --model <m> --domain <d> --quality <accepted|rejected> --latency <ms> --cost <c>',
  '  bayesroute rank    --store <file> [--domain <d>]',
  '  bayesroute inspect --store <file> [--model <m>] [--domain <d>]',
  '  bayesroute verify  --store <file>',
  '  bayesroute help',
  '  bayesroute --version',
  '',
  'All commands print JSON to stdout. Exit codes: 0 ok, 1 error, 64 usage, 65 data, 66 no input.',
].join('\n');

function usageError(io: CliIo, message: string): number {
  io.err(message);
  io.err(USAGE);
  return EXIT_USAGE;
}

async function readSnapshot(io: CliIo, path: string): Promise<StoreSnapshot> {
  const text = await io.readFile(path);
  return decodeSnapshot(text);
}

function loadedStore(snapshot: StoreSnapshot): PosteriorStore {
  const store = createMemoryStore();
  loadSnapshot(store, snapshot);
  return store;
}

function summaryLine(summary: ArmSummary): Record<string, unknown> {
  return {
    model: summary.model,
    domain: summary.domain,
    quality: Number(summary.quality.toFixed(4)),
    latencyMs: Number(summary.latencyMs.toFixed(2)),
    cost: Number(summary.cost.toFixed(2)),
    utility: Number(summary.utility.toFixed(4)),
    pulls: summary.pulls,
  };
}

async function cmdRoute(
  options: Readonly<Record<string, string | boolean>>,
  io: CliIo,
): Promise<number> {
  const modelsRaw = stringOption(options, 'models');
  if (modelsRaw === undefined) {
    return usageError(io, 'route requires --models <a,b,c>');
  }
  const models = modelsRaw
    .split(',')
    .map((model) => model.trim())
    .filter((model) => model.length > 0);
  if (models.length === 0) {
    return usageError(io, 'route requires at least one model in --models');
  }
  const storePath = stringOption(options, 'store');
  const store =
    storePath !== undefined ? loadedStore(await readSnapshot(io, storePath)) : undefined;
  const seed = numberOption(options, 'seed');
  const domain = stringOption(options, 'domain');
  const router = createBayesRoute({
    models,
    ...(seed !== undefined ? { seed } : {}),
    ...(store !== undefined ? { store } : {}),
  });
  const decision = router.route(domain !== undefined ? { domain } : {});
  io.out(
    JSON.stringify({ model: decision.model, domain: decision.domain, explored: decision.explored }),
  );
  return EXIT_OK;
}

async function cmdObserve(
  options: Readonly<Record<string, string | boolean>>,
  io: CliIo,
): Promise<number> {
  const storePath = stringOption(options, 'store');
  const model = stringOption(options, 'model');
  const domain = stringOption(options, 'domain');
  const quality = stringOption(options, 'quality');
  const latencyMs = numberOption(options, 'latency');
  const cost = numberOption(options, 'cost');
  if (
    storePath === undefined ||
    model === undefined ||
    domain === undefined ||
    quality === undefined ||
    latencyMs === undefined ||
    cost === undefined
  ) {
    return usageError(
      io,
      'observe requires --store, --model, --domain, --quality, --latency, and --cost',
    );
  }
  const accepted = quality === 'accepted' || quality === 'true';
  const rejected = quality === 'rejected' || quality === 'false';
  if (!accepted && !rejected) {
    return usageError(io, "observe --quality must be 'accepted' or 'rejected'");
  }
  let snapshot: StoreSnapshot;
  try {
    snapshot = await readSnapshot(io, storePath);
  } catch {
    snapshot = { version: 1, arms: [] };
  }
  const store = loadedStore(snapshot);
  const router = createBayesRoute({ models: [model], store });
  const arm = router.observe(model, domain, makeOutcome(accepted, latencyMs, cost));
  await io.writeFile(storePath, encodeSnapshot(store.snapshot()));
  io.out(
    JSON.stringify({
      model: arm.model,
      domain: arm.domain,
      pulls: arm.pulls,
      accepted: arm.accepted,
      rejected: arm.rejected,
    }),
  );
  return EXIT_OK;
}

async function cmdRank(
  options: Readonly<Record<string, string | boolean>>,
  io: CliIo,
): Promise<number> {
  const storePath = stringOption(options, 'store');
  if (storePath === undefined) {
    return usageError(io, 'rank requires --store <file>');
  }
  const domain = stringOption(options, 'domain');
  const snapshot = await readSnapshot(io, storePath);
  const summaries = snapshot.arms
    .filter((arm) => domain === undefined || arm.domain === domain)
    .map((arm) => armSummary(arm, DEFAULT_WEIGHTS, DEFAULT_SCALE))
    .sort((a, b) => b.utility - a.utility);
  io.out(JSON.stringify(summaries.map(summaryLine)));
  return EXIT_OK;
}

async function cmdInspect(
  options: Readonly<Record<string, string | boolean>>,
  io: CliIo,
): Promise<number> {
  const storePath = stringOption(options, 'store');
  if (storePath === undefined) {
    return usageError(io, 'inspect requires --store <file>');
  }
  const model = stringOption(options, 'model');
  const domain = stringOption(options, 'domain');
  const snapshot = await readSnapshot(io, storePath);
  const arms = snapshot.arms.filter(
    (arm) =>
      (model === undefined || arm.model === model) &&
      (domain === undefined || arm.domain === domain),
  );
  io.out(
    JSON.stringify(arms.map((arm) => summaryLine(armSummary(arm, DEFAULT_WEIGHTS, DEFAULT_SCALE)))),
  );
  return EXIT_OK;
}

async function cmdVerify(
  options: Readonly<Record<string, string | boolean>>,
  io: CliIo,
): Promise<number> {
  const storePath = stringOption(options, 'store');
  if (storePath === undefined) {
    return usageError(io, 'verify requires --store <file>');
  }
  const snapshot = await readSnapshot(io, storePath);
  io.out(JSON.stringify({ valid: true, version: snapshot.version, arms: snapshot.arms.length }));
  return EXIT_OK;
}

function formatError(error: unknown): string {
  if (isBayesRouteError(error)) {
    return `${error.code}: ${error.message}`;
  }
  return error instanceof Error ? error.message : String(error);
}

/** Run the CLI: parse args, dispatch the command, and return a process exit code. */
export async function runCli(
  argv: ReadonlyArray<string>,
  io: CliIo,
  context: CliContext,
): Promise<number> {
  const { command, options } = parseArgs(argv);
  if (options.version === true) {
    io.out(context.version);
    return EXIT_OK;
  }
  if (options.help === true || command === undefined || command === 'help') {
    io.out(USAGE);
    return EXIT_OK;
  }
  try {
    switch (command) {
      case 'route':
        return await cmdRoute(options, io);
      case 'observe':
        return await cmdObserve(options, io);
      case 'rank':
        return await cmdRank(options, io);
      case 'inspect':
        return await cmdInspect(options, io);
      case 'verify':
        return await cmdVerify(options, io);
      default:
        return usageError(io, `unknown command '${command}'`);
    }
  } catch (error) {
    io.err(formatError(error));
    return isBayesRouteError(error) ? EXIT_DATA : EXIT_ERROR;
  }
}
