/**
 * @takk/bayesroute, a Thompson-sampling Bayesian router for LLMs across quality, cost, and latency.
 *
 * Every (model, domain) arm carries three conjugate posteriors: a Beta over the probability of an
 * acceptable output, and two Gamma-Exponential posteriors over latency and cost. For each query the
 * router classifies a domain, samples one value from every posterior, scores the arms by the
 * multi-objective expected utility, and routes to the best draw (Thompson sampling), bounded by a
 * safe-exploration guard. After the real outcome is observed the posteriors update in closed form. This
 * module is the facade wiring the classifier, posterior store, sampler, utility, decision policy,
 * optional time-decay, and the tamper-evident audit log into one object. Every submodule is also a
 * standalone entry point for callers who want only the math.
 *
 * @example
 * ```ts
 * import { createBayesRoute } from '@takk/bayesroute';
 *
 * const router = createBayesRoute({ models: ['gpt-5.5', 'haiku-4.5'], seed: 1 });
 * const decision = router.route({ text: 'summarize this contract', domain: 'legal' });
 * // ... call decision.model, measure the result ...
 * router.observeDecision(decision, { quality: true, latencyMs: 820, cost: 1300 });
 * console.log(router.rank('legal')[0]);
 * ```
 *
 * @packageDocumentation
 */

