/** What the caller's `call` returns to {@link BayesRoute.run}: the result, its quality, and the cost. */
export interface RunResult<TResult> {
  /** The model's actual output, passed straight back to the caller. */
  readonly result: TResult;
  /** Whether the output is acceptable, from any judge, scorer, or human. */
  readonly quality: Outcome['quality'];
  /** The observed cost (token usage or money). */
  readonly cost: number;
  /** The observed latency in milliseconds. When omitted, `run` measures it with the configured clock. */
  readonly latencyMs?: number;
}

/** What {@link BayesRoute.run} returns: the decision, the folded outcome, the result, and the updated arm. */
export interface RunOutcome<TResult> {
  readonly decision: RouteDecision;
  readonly outcome: Outcome;
  readonly result: TResult;
  readonly record: ArmRecord;
}

/** Options for {@link createBayesRoute}. */
export interface BayesRouteOptions {
  /** The candidate models the router selects among. Must be non-empty. */
  readonly models: ReadonlyArray<string>;
  /** Multi-objective weights. Defaults to {@link DEFAULT_WEIGHTS}. */
  readonly weights?: UtilityWeights;
  /** Reference scales for latency and cost. Defaults to {@link DEFAULT_SCALE}. */
  readonly scale?: UtilityScale;
  /** Prior for fresh arms. Defaults to a uniform quality prior plus weak latency and cost priors. */
  readonly prior?: ArmPrior;
  /** Query classifier. Defaults to honoring an explicit domain, otherwise the shared default domain. */
  readonly classifier?: QueryClassifier;
  /** Safe-exploration bounds. Defaults to {@link DEFAULT_SAFE_EXPLORATION}. */
  readonly safeExploration?: SafeExplorationPolicy;
  /** Time-decay of evidence. Off by default. */
  readonly decay?: DecayOptions;
  /** Credible-interval level for summaries. Defaults to 0.95. */
  readonly level?: number;
  /** Seed for the Thompson sampler, for reproducible routing. Defaults to a non-deterministic source. */
  readonly seed?: number;
  /** Clock for observation timestamps, decay, and audit. Defaults to `Date.now`. */
  readonly clock?: Clock;
  /** A custom posterior store. Defaults to in-memory. */
  readonly store?: PosteriorStore;
  /** Record every routing decision and observation to a tamper-evident audit log. Off by default. */
  readonly audit?: boolean;
}

/** A fully wired BayesRoute instance. */
export interface BayesRoute {
  /** Route one query: classify the domain, Thompson-sample the arms, and apply the safe-exploration guard. */
  route(features?: QueryFeatures): RouteDecision;
  /**
   * Route, call the chosen model, and fold the outcome back, in one step. The `call` receives the
   * chosen model and domain and returns the result, its quality, and the cost; latency is measured with
   * the configured clock unless the caller provides it. This is the frictionless one-call path.
   */
  run<TResult>(
    features: QueryFeatures | undefined,
    call: (model: string, domain: string) => Promise<RunResult<TResult>>,
  ): Promise<RunOutcome<TResult>>;
  /** Fold one observed outcome into a (model, domain) arm and persist it. */
  observe(model: string, domain: string, outcome: Outcome): ArmRecord;
  /** Fold an outcome into the arm chosen by a prior {@link RouteDecision}. */
  observeDecision(decision: RouteDecision, outcome: Outcome): ArmRecord;
  /** The current record for an arm, decay applied, creating a fresh one from the prior if unseen. */
  arm(model: string, domain: string): ArmRecord;
  /** Calibrated summaries: for one domain across all models, or for every observed arm. */
  summary(domain?: string): ArmSummary[];
  /** Summaries ranked by expected utility, best first. */
  rank(domain?: string): ArmSummary[];
  /** The configured candidate models. */
  models(): ReadonlyArray<string>;
  /** Every domain seen in the store. */
  domains(): string[];
  /** A portable snapshot of the whole store. */
  snapshot(): StoreSnapshot;
  /** Merge a snapshot or its JSON encoding into the store. */
  load(input: StoreSnapshot | string): void;
  /** The audit log, present only when `audit` was enabled. */
  auditLog(): AuditLog | undefined;
  /** Seal the audit log into a tamper-evident root. Throws when auditing is disabled. */
  seal(): Promise<AuditSeal>;
  /** Verify the audit log against a seal. Throws when auditing is disabled. */
  verify(seal: AuditSeal): Promise<VerifyResult>;
}

/** Create a BayesRoute instance with the given options. */
export function createBayesRoute(options: BayesRouteOptions): BayesRoute {
  const models = [...options.models];
  if (models.length === 0) {
    throw new BayesRouteError('ERR_NO_ARMS', 'createBayesRoute requires at least one model');
  }
  const weights = options.weights ?? DEFAULT_WEIGHTS;
  assertWeights(weights);
  const scale = options.scale ?? DEFAULT_SCALE;
  assertScale(scale);
  const prior: ArmPrior = options.prior ?? defaultArmPrior(scale);
  const classifier = options.classifier ?? defaultClassifier;
  const safeExploration = options.safeExploration ?? DEFAULT_SAFE_EXPLORATION;
  const decay = options.decay;
  const level = options.level;
  const clock: Clock = options.clock ?? Date.now;
  const rng: Rng = options.seed !== undefined ? mulberry32(options.seed) : Math.random;
  const store: PosteriorStore = options.store ?? createMemoryStore();
  let audit: AuditLog | undefined = options.audit ? createAuditLog() : undefined;

  function record(audited: () => AuditLog): void {
    if (audit) {
      audit = audited();
    }
  }

  function stored(model: string, domain: string, at: number): ArmRecord {
    return store.get(model, domain) ?? initialArm(model, domain, prior, at);
  }

  /** The arm viewed at the current time, with decay applied but not persisted. */
  function view(model: string, domain: string): ArmRecord {
    const now = clock();
    const base = stored(model, domain, now);
    return decay ? decayArm(base, prior, decay, now) : base;
  }

  function observe(model: string, domain: string, outcome: Outcome): ArmRecord {
    const now = clock();
    const base = decay
      ? decayArm(stored(model, domain, now), prior, decay, now)
      : stored(model, domain, now);
    const next = observeArm(base, outcome, now);
    store.set(next);
    record(() =>
      appendEntry(
        audit ?? createAuditLog(),
        'observation',
        `${model}/${domain}:${isAccepted(outcome.quality) ? 'accepted' : 'rejected'}`,
        now,
        {
          model,
          domain,
          accepted: isAccepted(outcome.quality),
          latencyMs: outcome.latencyMs,
          cost: outcome.cost,
        },
      ),
    );
    return next;
  }

  function summary(domain?: string): ArmSummary[] {
    if (domain !== undefined) {
      return models.map((model) => armSummary(view(model, domain), weights, scale, level));
    }
    return store
      .keys()
      .map((key) => armSummary(view(key.model, key.domain), weights, scale, level));
  }

  function routeQuery(features?: QueryFeatures): RouteDecision {
    const now = clock();
    const domain = classifier(features ?? {});
    const arms = models.map((model) => {
      const base = stored(model, domain, now);
      return decay ? decayArm(base, prior, decay, now) : base;
    });
    const decision = thompsonRoute(arms, weights, scale, rng);
    const guarded = applySafeExploration(decision, arms, weights, scale, safeExploration);
    record(() =>
      appendEntry(audit ?? createAuditLog(), 'route', `${guarded.model}/${guarded.domain}`, now, {
        domain: guarded.domain,
        model: guarded.model,
        explored: guarded.explored,
      }),
    );
    return guarded;
  }

  async function runQuery<TResult>(
    features: QueryFeatures | undefined,
    call: (model: string, domain: string) => Promise<RunResult<TResult>>,
  ): Promise<RunOutcome<TResult>> {
    const decision = routeQuery(features);
    const startedAt = clock();
    const produced = await call(decision.model, decision.domain);
    const measured = clock() - startedAt;
    const latencyMs = produced.latencyMs ?? (measured > 0 ? measured : 1e-6);
    const outcome: Outcome = { quality: produced.quality, latencyMs, cost: produced.cost };
    const updated = observe(decision.model, decision.domain, outcome);
    return { decision, outcome, result: produced.result, record: updated };
  }

  return {
    route: routeQuery,
    run: runQuery,
    observe,
    observeDecision: (decision, outcome) => observe(decision.model, decision.domain, outcome),
    arm: (model, domain) => view(model, domain),
    summary,
    rank: (domain) => summary(domain).sort((a, b) => b.utility - a.utility),
    models: () => [...models],
    domains: () => {
      const seen = new Set<string>();
      for (const key of store.keys()) {
        seen.add(key.domain);
      }
      return [...seen];
    },
    snapshot: () => store.snapshot(),
    load: (input) => {
      const snapshot = typeof input === 'string' ? decodeSnapshot(input) : input;
      loadSnapshot(store, snapshot);
    },
    auditLog: () => audit,
    seal: async () => sealAuditLog(requireAudit(audit)),
    verify: async (seal) => verifyAuditLog(requireAudit(audit), seal),
  };
}

function requireAudit(audit: AuditLog | undefined): AuditLog {
  if (!audit) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      'audit is disabled; construct BayesRoute with { audit: true }',
    );
  }
  return audit;
}
