/**
 * The Thompson sampler, the heart of the router.
 *
 * For each query the sampler draws one value from every arm's three posteriors, scores each arm by the
 * multi-objective expected utility, and routes to the arm whose draw scored highest. Because the draws
 * come from the posteriors, an arm that is rarely tried but might be excellent still gets its turn in
 * proportion to the probability it is actually best, which is what gives Thompson sampling its bounded
 * regret. The greedy incumbent, the arm with the highest posterior-mean utility, is reported alongside
 * so the safe-exploration policy can decide whether the explored pick is allowed.
 *
 * @packageDocumentation
 */

import { sampleFrom as sampleQuality } from '../beta/index.js';
import { BayesRouteError } from '../errors.js';
import { sampleValue } from '../gamma/index.js';
import type { Rng } from '../rng.js';
import type { ArmDraw, ArmRecord, RouteDecision, UtilityScale, UtilityWeights } from '../types.js';
import { DEFAULT_SCALE, DEFAULT_WEIGHTS, expectedUtility, meanUtility } from '../utility/index.js';

/** Draw one Thompson sample for a single arm and score its expected utility. */
export function sampleArm(
  record: ArmRecord,
  weights: UtilityWeights = DEFAULT_WEIGHTS,
  scale: UtilityScale = DEFAULT_SCALE,
  rng: Rng = Math.random,
): ArmDraw {
  const quality = sampleQuality(record.posterior.quality, rng);
  const latencyMs = sampleValue(record.posterior.latency, rng);
  const cost = sampleValue(record.posterior.cost, rng);
  return {
    model: record.model,
    domain: record.domain,
    quality,
    latencyMs,
    cost,
    utility: expectedUtility(quality, latencyMs, cost, weights, scale),
  };
}

/** The greedy incumbent: the arm with the highest posterior-mean utility. Throws on an empty set. */
export function greedyIncumbent(
  arms: ReadonlyArray<ArmRecord>,
  weights: UtilityWeights = DEFAULT_WEIGHTS,
  scale: UtilityScale = DEFAULT_SCALE,
): ArmRecord {
  const first = arms[0];
  if (first === undefined) {
    throw new BayesRouteError('ERR_NO_ARMS', 'greedyIncumbent requires at least one arm');
  }
  let best = first;
  let bestUtility = meanUtility(first, weights, scale);
  for (let i = 1; i < arms.length; i += 1) {
    const candidate = arms[i];
    if (candidate === undefined) {
      continue;
    }
    const utility = meanUtility(candidate, weights, scale);
    if (utility > bestUtility) {
      best = candidate;
      bestUtility = utility;
    }
  }
  return best;
}

/**
 * Route one query by Thompson sampling over the arms. Returns the chosen arm, every arm's draw sorted
 * by utility (highest first), and whether the pick differs from the greedy incumbent (explored).
 */
export function thompsonRoute(
  arms: ReadonlyArray<ArmRecord>,
  weights: UtilityWeights = DEFAULT_WEIGHTS,
  scale: UtilityScale = DEFAULT_SCALE,
  rng: Rng = Math.random,
): RouteDecision {
  if (arms.length === 0) {
    throw new BayesRouteError('ERR_NO_ARMS', 'thompsonRoute requires at least one arm');
  }
  const draws = arms.map((arm) => sampleArm(arm, weights, scale, rng));
  const sorted = [...draws].sort((a, b) => b.utility - a.utility);
  const pick = sorted[0];
  if (pick === undefined) {
    throw new BayesRouteError('ERR_NO_ARMS', 'thompsonRoute produced no draws');
  }
  const incumbent = greedyIncumbent(arms, weights, scale);
  const explored = pick.model !== incumbent.model || pick.domain !== incumbent.domain;
  return { model: pick.model, domain: pick.domain, draws: sorted, explored };
}
