/**
 * The (model, domain) arm: a bundle of three conjugate posteriors.
 *
 * Each arm carries a Beta over quality, a Gamma-Exponential over latency, and a Gamma-Exponential over
 * cost, plus the observed counts. Seeding a fresh arm, folding one outcome into all three posteriors in
 * closed form, and producing a calibrated point-and-interval summary all live here. This is the unit
 * the sampler draws from and the store persists.
 *
 * @packageDocumentation
 */

import {
  credibleInterval as betaCredibleInterval,
  betaMean,
  isAccepted,
  UNIFORM_PRIOR,
  updateQuality,
} from '../beta/index.js';
import {
  expectedValueMean,
  gammaPriorFromMean,
  updateValue,
  valueCredibleInterval,
} from '../gamma/index.js';
import type {
  ArmPrior,
  ArmRecord,
  ArmSummary,
  Outcome,
  UtilityScale,
  UtilityWeights,
} from '../types.js';
import { DEFAULT_SCALE, DEFAULT_WEIGHTS, expectedUtility } from '../utility/index.js';

export type { ArmPosterior, ArmPrior, ArmRecord, ArmSummary } from '../types.js';

/** Default credible level for arm summaries. */
export const DEFAULT_CREDIBLE_LEVEL = 0.95;

/**
 * Build a default arm prior from the utility scale: a uniform quality prior and weak latency and cost
 * priors centered on the reference scales, so a fresh arm starts neutral and adapts fast.
 */
export function defaultArmPrior(scale: UtilityScale = DEFAULT_SCALE): ArmPrior {
  return {
    quality: UNIFORM_PRIOR,
    latency: gammaPriorFromMean(scale.latencyMs),
    cost: gammaPriorFromMean(scale.cost),
  };
}

/** Seed a fresh arm for a (model, domain) pair from the given prior. */
export function initialArm(model: string, domain: string, prior: ArmPrior, at = 0): ArmRecord {
  return {
    model,
    domain,
    posterior: { quality: prior.quality, latency: prior.latency, cost: prior.cost },
    pulls: 0,
    accepted: 0,
    rejected: 0,
    lastObservedAt: at,
  };
}

/** Fold one observed outcome into all three posteriors and bump the counts. */
export function observeArm(record: ArmRecord, outcome: Outcome, at: number): ArmRecord {
  const accepted = isAccepted(outcome.quality);
  return {
    model: record.model,
    domain: record.domain,
    posterior: {
      quality: updateQuality(record.posterior.quality, outcome.quality),
      latency: updateValue(record.posterior.latency, outcome.latencyMs),
      cost: updateValue(record.posterior.cost, outcome.cost),
    },
    pulls: record.pulls + 1,
    accepted: record.accepted + (accepted ? 1 : 0),
    rejected: record.rejected + (accepted ? 0 : 1),
    lastObservedAt: at,
  };
}

/** Produce a calibrated point-and-interval summary of one arm under the given weights and scale. */
export function armSummary(
  record: ArmRecord,
  weights: UtilityWeights = DEFAULT_WEIGHTS,
  scale: UtilityScale = DEFAULT_SCALE,
  level: number = DEFAULT_CREDIBLE_LEVEL,
): ArmSummary {
  const quality = betaMean(record.posterior.quality);
  const latencyMs = expectedValueMean(record.posterior.latency);
  const cost = expectedValueMean(record.posterior.cost);
  return {
    model: record.model,
    domain: record.domain,
    quality,
    qualityInterval: betaCredibleInterval(record.posterior.quality, level),
    latencyMs,
    latencyInterval: valueCredibleInterval(record.posterior.latency, level),
    cost,
    costInterval: valueCredibleInterval(record.posterior.cost, level),
    utility: expectedUtility(quality, latencyMs, cost, weights, scale),
    pulls: record.pulls,
  };
}
