/**
 * The multi-objective expected utility.
 *
 * A router does not optimize a single metric; it trades quality against latency and cost. The utility
 * is a weighted combination where higher quality is rewarded and latency and cost are penalized after
 * being normalized onto the quality scale by reference values. The same function scores a sampled draw
 * (Thompson sampling) and a posterior mean (the greedy incumbent), so exploration and exploitation are
 * measured on one ruler.
 *
 * @packageDocumentation
 */

import { betaMean } from '../beta/index.js';
import { BayesRouteError } from '../errors.js';
import { expectedValueMean } from '../gamma/index.js';
import type { ArmRecord, UtilityScale, UtilityWeights } from '../types.js';

export type { UtilityScale, UtilityWeights } from '../types.js';

/** Default weights: quality dominates, latency and cost each carry a quarter of its weight. */
export const DEFAULT_WEIGHTS: UtilityWeights = { quality: 1, latency: 0.25, cost: 0.25 };

/** Default reference scales: one second of latency and one thousand cost units map to one penalty unit. */
export const DEFAULT_SCALE: UtilityScale = { latencyMs: 1000, cost: 1000 };

/** Throw unless the weights are finite and non-negative with at least one positive weight. */
export function assertWeights(w: UtilityWeights): void {
  const values = [w.quality, w.latency, w.cost];
  for (const value of values) {
    if (!Number.isFinite(value) || value < 0) {
      throw new BayesRouteError(
        'ERR_INVALID_INPUT',
        `utility weights must be finite and non-negative, received ${JSON.stringify(w)}`,
      );
    }
  }
  if (w.quality + w.latency + w.cost <= 0) {
    throw new BayesRouteError('ERR_INVALID_INPUT', 'at least one utility weight must be positive');
  }
}

/** Throw unless the reference scales are finite and strictly positive. */
export function assertScale(s: UtilityScale): void {
  if (
    !Number.isFinite(s.latencyMs) ||
    s.latencyMs <= 0 ||
    !Number.isFinite(s.cost) ||
    s.cost <= 0
  ) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `utility scale must be finite and positive, received ${JSON.stringify(s)}`,
    );
  }
}

/**
 * The expected utility of a single (quality, latency, cost) point. Quality is a probability in [0, 1];
 * latency is milliseconds; cost is in the consumer's own unit. Higher is better.
 */
export function expectedUtility(
  quality: number,
  latencyMs: number,
  cost: number,
  weights: UtilityWeights = DEFAULT_WEIGHTS,
  scale: UtilityScale = DEFAULT_SCALE,
): number {
  return (
    weights.quality * quality -
    weights.latency * (latencyMs / scale.latencyMs) -
    weights.cost * (cost / scale.cost)
  );
}

/** The expected utility of an arm computed from its posterior means, the greedy score. */
export function meanUtility(
  record: ArmRecord,
  weights: UtilityWeights = DEFAULT_WEIGHTS,
  scale: UtilityScale = DEFAULT_SCALE,
): number {
  return expectedUtility(
    betaMean(record.posterior.quality),
    expectedValueMean(record.posterior.latency),
    expectedValueMean(record.posterior.cost),
    weights,
    scale,
  );
}
