/**
 * The safe-exploration policy.
 *
 * Thompson sampling explores by design, but unbounded exploration can route a production query to an
 * arm that is probably worse, a regression the caller never agreed to. The policy caps that risk: an
 * explored pick is allowed when the arm is still under-explored (fewer than `minPulls` observations),
 * or when its posterior-mean utility is within `maxRegretMargin` of the greedy incumbent. Otherwise the
 * router falls back to the incumbent. This keeps the long-run regret bounded while never letting a
 * single decision stray too far from the best known arm.
 *
 * @packageDocumentation
 */

import { greedyIncumbent } from '../sampler/index.js';
import type {
  ArmRecord,
  RouteDecision,
  SafeExplorationPolicy,
  UtilityScale,
  UtilityWeights,
} from '../types.js';
import { DEFAULT_SCALE, DEFAULT_WEIGHTS, meanUtility } from '../utility/index.js';

export type { SafeExplorationPolicy } from '../types.js';

/** A sensible default: arms under ten pulls explore freely, otherwise stay within 0.05 utility of best. */
export const DEFAULT_SAFE_EXPLORATION: SafeExplorationPolicy = {
  minPulls: 10,
  maxRegretMargin: 0.05,
};

/** Throw unless the policy parameters are finite and non-negative. */
export function assertSafeExploration(policy: SafeExplorationPolicy): void {
  if (
    !Number.isFinite(policy.minPulls) ||
    policy.minPulls < 0 ||
    !Number.isFinite(policy.maxRegretMargin) ||
    policy.maxRegretMargin < 0
  ) {
    throw new Error(
      `safe-exploration policy must be finite and non-negative, received ${JSON.stringify(policy)}`,
    );
  }
}

/**
 * Apply the safe-exploration guard to a Thompson decision. When the explored pick is neither
 * under-explored nor within the regret margin of the incumbent, fall back to the incumbent and clear
 * the explored flag. A greedy (non-explored) decision is returned unchanged.
 */
export function applySafeExploration(
  decision: RouteDecision,
  arms: ReadonlyArray<ArmRecord>,
  weights: UtilityWeights = DEFAULT_WEIGHTS,
  scale: UtilityScale = DEFAULT_SCALE,
  policy: SafeExplorationPolicy = DEFAULT_SAFE_EXPLORATION,
): RouteDecision {
  if (!decision.explored) {
    return decision;
  }
  const picked = arms.find((arm) => arm.model === decision.model && arm.domain === decision.domain);
  if (picked === undefined) {
    return decision;
  }
  if (picked.pulls < policy.minPulls) {
    return decision;
  }
  const incumbent = greedyIncumbent(arms, weights, scale);
  const regret = meanUtility(incumbent, weights, scale) - meanUtility(picked, weights, scale);
  if (regret > policy.maxRegretMargin) {
    return {
      model: incumbent.model,
      domain: incumbent.domain,
      draws: decision.draws,
      explored: false,
    };
  }
  return decision;
}
