/**
 * Time-decay of evidence.
 *
 * Models drift: a provider silently deprecates a checkpoint, a domain shifts, last quarter's latency no
 * longer predicts this quarter's. Decay relaxes every posterior back toward its prior as time passes, so
 * stale evidence loses weight and the router re-explores. At each step the pseudo-counts above the prior
 * are scaled by `0.5 ^ (elapsed / halfLifeMs)`; one half-life halves the accumulated evidence. The raw
 * observed counts are preserved as history, only the posteriors are relaxed.
 *
 * @packageDocumentation
 */

import { BayesRouteError } from '../errors.js';
import type { ArmPrior, ArmRecord, BetaPosterior, DecayOptions, GammaPosterior } from '../types.js';

export type { DecayOptions } from '../types.js';

/** The retention factor in (0, 1] for an elapsed time and half-life. */
export function retention(elapsedMs: number, halfLifeMs: number): number {
  if (!Number.isFinite(halfLifeMs) || halfLifeMs <= 0) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `decay requires halfLifeMs > 0, received ${halfLifeMs}`,
    );
  }
  if (!Number.isFinite(elapsedMs) || elapsedMs <= 0) {
    return 1;
  }
  return 0.5 ** (elapsedMs / halfLifeMs);
}

function decayBeta(posterior: BetaPosterior, prior: BetaPosterior, factor: number): BetaPosterior {
  return {
    alpha: prior.alpha + (posterior.alpha - prior.alpha) * factor,
    beta: prior.beta + (posterior.beta - prior.beta) * factor,
  };
}

function decayGamma(
  posterior: GammaPosterior,
  prior: GammaPosterior,
  factor: number,
): GammaPosterior {
  return {
    shape: prior.shape + (posterior.shape - prior.shape) * factor,
    rate: prior.rate + (posterior.rate - prior.rate) * factor,
  };
}

/**
 * Return a copy of the arm with its posteriors relaxed toward the prior for the time elapsed between
 * its last observation and `now`. The observed counts are kept; `lastObservedAt` advances to `now` so
 * decay is not applied twice. A non-positive elapsed time returns the record unchanged.
 */
export function decayArm(
  record: ArmRecord,
  prior: ArmPrior,
  options: DecayOptions,
  now: number,
): ArmRecord {
  const factor = retention(now - record.lastObservedAt, options.halfLifeMs);
  if (factor >= 1) {
    return record;
  }
  return {
    model: record.model,
    domain: record.domain,
    posterior: {
      quality: decayBeta(record.posterior.quality, prior.quality, factor),
      latency: decayGamma(record.posterior.latency, prior.latency, factor),
      cost: decayGamma(record.posterior.cost, prior.cost, factor),
    },
    pulls: record.pulls,
    accepted: record.accepted,
    rejected: record.rejected,
    lastObservedAt: now,
  };
}
